-- Demo fixture – idempotent rerun does not duplicate
-- Mirrors backend/app/seed.py: 1 society, 2 flat categories, 8 flats
-- with varied opening_due (2000, 0, 500), POCs, 6 receipts (including -500 advance),
-- 1 admin + 1 collector user, notifications logged in test mode.
-- Run: psql -f backend/seed.sql  or  uv run python -m app.seed

-- Society (id 00000000-0000-0000-0000-000000000001 is seeded via migration, ensure)
VALUES ('00000000-0000-0000-0000-000000000001', 'Manzil Pilot Society', 'Pilot Location', 'Pune')
ON CONFLICT (id) DO NOTHING;

-- Categories (already in migration, ensure)
ON CONFLICT (id) DO NOTHING;

-- Funds (already in migration)
ON CONFLICT (id) DO NOTHING;

-- Users / memberships (collector demo; admin already seeded)
VALUES ('00000000-0000-0000-0000-000000000202', '+919000000100', 'Collector Demo', gen_random_uuid())
ON CONFLICT (id) DO NOTHING;

VALUES ('00000000-0000-0000-0000-000000000302', '00000000-0000-0000-0000-000000000202', '00000000-0000-0000-0000-000000000001', 'ACTIVE')
ON CONFLICT (id) DO NOTHING;

SELECT '00000000-0000-0000-0000-000000000302', id FROM roles WHERE key='COLLECTOR'
ON CONFLICT DO NOTHING;

-- Flats DEMO-A101..A108
ON CONFLICT (id) DO NOTHING;

-- Persons
ON CONFLICT (id) DO NOTHING;

-- Occupants (ON CONFLICT covers duplicate; partial index handles active role uniqueness)
ON CONFLICT (flat_id, person_id, role) DO NOTHING;

-- Opening dues (PRIMARY KEY flat_id)
ON CONFLICT (flat_id) DO UPDATE SET amount = EXCLUDED.amount;

-- Receipts (6 demo receipts, fund Main Fund, collected_by admin membership)
ON CONFLICT (id) DO NOTHING;

-- Notifications (test-mode LOGGED for observability)
ON CONFLICT (id) DO NOTHING;
